export function initStorageAdmin(c){const {$,state,req,element,button,busy,toast,showSection}=c;const rpc=(action,payload={})=>req('/rest/v1/rpc/storage_maintenance',{method:'POST',body:{action,payload}});const tab=button('◴ البيانات والمساحة',()=>showSection('storage'));tab.id='storage-tab';tab.hidden=true;document.querySelector('.app-nav').append(tab);const section=element('section',undefined,'card');section.id='storage-section';section.hidden=true;section.innerHTML='<div class="feed-heading"><h2>البيانات والمساحة</h2><button id="storage-refresh" class="secondary">↻ تحديث القياس</button></div><p class="muted">قياس مباشر لهذا المشروع. الحدود أدناه مرجعية وليست قراءة للفوترة؛ تخزين الملفات قد يكون مشتركًا مع مشاريع المنظمة. لا تغيّر هذه الشاشة الاشتراك ولا تشتري مساحة.</p><div id="storage-metrics" class="storage-metrics"></div><div id="storage-records" class="intro-pills"></div><p id="storage-measured" class="muted"></p><details><summary>الخطة والحدود المرجعية</summary><form id="storage-limits-form"><label>مرجع الخطة<select id="storage-plan"><option value="free">Free — مجاني</option><option value="pro">Pro — مدفوع</option><option value="custom">حدود مخصصة</option></select></label><label>حصة قاعدة البيانات بالميجابايت<input id="storage-db-limit" type="number" min="1" max="100000000" required></label><label>حصة الملفات بالميجابايت<input id="storage-file-limit" type="number" min="1" max="100000000" required></label><button class="secondary">حفظ الحدود للعرض</button><p class="muted">المرجع: Free قاعدة 500MB وملفات 1GB؛ Pro قرص 8GB وملفات 100GB. تحقق من اشتراكك وحدودك الفعلية في لوحة Supabase قبل تغيير المرجع. بيانات النقل الشهري والمستخدمين النشطين والفوترة غير متاحة هنا.</p><a href="https://supabase.com/dashboard/project/dlkykiducjimwehfhxfq" target="_blank" rel="noopener">لوحة Supabase</a></form></details><h3>توفير مساحة بذكاء</h3><p class="muted">الصور: معاينة حجم النسخة المضغوطة أولًا، ثم استبدال الصور التي توفر 15٪ على الأقل دون قص. الدردشة: تُحذف رسائل المحادثة فقط إذا كانت آخر رسالة فيها أقدم من 10 أشهر؛ تُحفظ كل الرسائل القديمة داخل أي محادثة نشطة.</p><div class="post-actions"><button id="storage-scan-images" class="secondary">فحص ضغط الصور</button><button id="storage-preview-chats" class="secondary">فحص الدردشات الخاملة</button></div><div id="storage-image-review"></div><div id="storage-chat-review"></div><p id="storage-operation" role="status"></p><details><summary>تفاصيل التخزين والجداول</summary><div id="storage-detail"></div></details>';$('approved').append(section);let running=false,previewUrl,generation=0;const scanned=new Set();
 const size=n=>{n=Number(n)||0;return n>=1073741824?(n/1073741824).toFixed(2)+' GB':n>=1048576?(n/1048576).toFixed(2)+' MB':(n/1024).toFixed(1)+' KB';};
 async function load(){const data=await rpc('usage');if(state.profile?.role!=='admin')return;const box=$('storage-metrics');box.replaceChildren();for(const [title,used,limit]of[['قاعدة البيانات',data.database_bytes,data.limits.database_limit],['ملفات وصور المشروع',data.storage_bytes,data.limits.file_limit]]){const card=element('article',undefined,'storage-meter');card.append(element('h3',title),element('strong',size(used)+' مستخدم'),element('p',size(Math.max(0,limit-used))+' متبقٍ من '+size(limit)+' (مرجعي)'));const progress=element('progress');progress.max=100;progress.value=Math.min(100,used/limit*100);progress.setAttribute('aria-label',title);card.append(progress,element('small',(used/limit*100).toFixed(2)+'٪'));if(used/limit>=.8)card.append(element('p','اقترب الاستهلاك من الحصة المرجعية.','danger'));box.append(card);}box.append(element('article','الإجمالي المقاس: '+size(Number(data.database_bytes)+Number(data.storage_bytes)),'storage-meter'));$('storage-records').replaceChildren();for(const [key,title]of[['users','عضو'],['news','خبر'],['comments','تعليق'],['messages','رسالة']])$('storage-records').append(element('span',data.records[key]+' '+title));$('storage-measured').textContent='آخر قياس: '+new Date(data.measured_at).toLocaleString('ar-SA')+' — الحصة المرجعية '+data.limits.plan+'. حذف الرسائل يتيح إعادة استخدام المساحة، ولا يضمن انخفاض حجم القرص فورًا.';$('storage-plan').value=data.limits.plan;$('storage-db-limit').value=data.limits.database_limit/1048576;$('storage-file-limit').value=data.limits.file_limit/1048576;const detail=$('storage-detail');detail.replaceChildren();for(const b of data.buckets)detail.append(element('p',b.bucket_id+' · '+b.files+' ملف · '+size(b.bytes)));for(const t of data.tables)detail.append(element('p',t.schema+'.'+t.name+' · '+size(t.bytes)));}
 $('storage-refresh').onclick=()=>busy($('storage-refresh'),load);$('storage-plan').onchange=()=>{const plan=$('storage-plan').value;if(plan==='custom')return;$('storage-db-limit').value=plan==='free'?500:8192;$('storage-file-limit').value=plan==='free'?1024:102400;};$('storage-limits-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await rpc('limits',{plan:$('storage-plan').value,database_limit:Math.round(Number($('storage-db-limit').value)*1048576),file_limit:Math.round(Number($('storage-file-limit').value)*1048576)});await load();toast('حُفظت الحدود المرجعية للعرض.');});};
 async function prepareImage(info){const signed=await req('/storage/v1/object/sign/'+info.bucket+'/'+info.path.split('/').map(encodeURIComponent).join('/'),{method:'POST',body:{expiresIn:600}});info.preview_src='https://dlkykiducjimwehfhxfq.supabase.co/storage/v1'+signed.signedURL;const response=await fetch(info.preview_src);if(!response.ok)throw new Error('تعذّر تنزيل الصورة');const bitmap=await createImageBitmap(await response.blob()),canvas=document.createElement('canvas'),scale=Math.min(1,(info.bucket==='profile-images'?512:1280)/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise(r=>canvas.toBlob(r,'image/jpeg',.72));}
 $('storage-scan-images').onclick=()=>busy($('storage-scan-images'),async()=>{if(running)throw new Error('انتظر انتهاء العملية الحالية.');running=true;const version=generation;let scanFailed=0;const candidates=[];try{const images=(await rpc('images')).filter(i=>i.bytes>30000&&!scanned.has(i.bucket+'/'+i.path+':'+i.bytes)).slice(0,50);for(let i=0;i<images.length;i++){$('storage-operation').textContent='فحص الصورة '+(i+1)+' من '+images.length;try{const blob=await prepareImage(images[i]);if(version!==generation)return;scanned.add(images[i].bucket+'/'+images[i].path+':'+images[i].bytes);if(blob&&blob.size<images[i].bytes*.85)candidates.push({...images[i],blob});}catch{scanFailed++;}}if(version!==generation)return;const review=$('storage-image-review');review.replaceChildren();const saving=candidates.reduce((n,i)=>n+i.bytes-i.blob.size,0);review.append(element('h4','نتيجة فحص الصور'),element('p',candidates.length+' صورة قابلة للضغط، ووفر متوقع '+size(saving)+'. الدفعة حتى 50 صورة لحماية ذاكرة الجوال. الاستبدال يغيّر جودة الصورة ولا يمكن التراجع عنه من هذه الشاشة.'));if(candidates.length){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(candidates[0].blob);const sample=element('div',undefined,'compression-preview');for(const [title,src]of[['الصورة الحالية',candidates[0].preview_src],['معاينة الضغط',previewUrl]]){const figure=element('figure'),image=element('img');image.src=src;image.alt=title;figure.append(image,element('figcaption',title));sample.append(figure);}review.append(sample);}if(candidates.length)review.append(button('تأكيد ضغط '+candidates.length+' صورة',async()=>{if(running)throw new Error('توجد عملية جارية.');if(!confirm('استبدال '+candidates.length+' صورة بنسخ JPEG مضغوطة لتوفير '+size(saving)+'؟ قد تنخفض الجودة قليلًا.'))return;running=true;let saved=0,done=0,failed=0;try{for(const image of candidates){if(version!==generation)return;$('storage-operation').textContent='حفظ الصور '+(done+failed+1)+' من '+candidates.length;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(image.blob);});const result=await req('/functions/v1/family-storage',{method:'POST',body:{action:'compress',bucket:image.bucket,path:image.path,expected_bytes:image.bytes,data}});saved+=result.saved_bytes;done++;}catch{failed++;}}review.replaceChildren(element('p','ضُغطت '+done+' صورة، الوفر الفعلي '+size(saved)+(failed?'؛ تعذّر حفظ '+failed+' صورة.':'')));await load();}finally{running=false;$('storage-operation').textContent='انتهى ضغط الصور.';}},'primary'));$('storage-operation').textContent='اكتمل الفحص؛ لم تُغيّر الصور بعد.'+(scanFailed?' تعذّر فحص '+scanFailed+' صورة.':'');}finally{running=false;}});
 $('storage-preview-chats').onclick=()=>busy($('storage-preview-chats'),async()=>{const data=await rpc('preview');const box=$('storage-chat-review');box.replaceChildren(element('h4','الدردشات الخاملة لأكثر من 10 أشهر'),element('p',data.rooms+' محادثة، '+data.messages+' رسالة. حجم محتوى تقريبي '+size(data.estimated_bytes)+'. آخر رسالة قبل '+new Date(data.cutoff).toLocaleDateString('ar-SA')+'.'));if(data.messages)box.append(button('تأكيد الحذف النهائي للرسائل الخاملة',async()=>{if(running)throw new Error('انتظر انتهاء العملية الحالية.');const current=await rpc('preview');if(!current.messages){toast('لا توجد رسائل مؤهلة للحذف.');return;}if(!confirm('حذف '+current.messages+' رسالة نهائيًا من '+current.rooms+' محادثة خاملة؟ ستُعاد مراجعة تاريخ آخر رسالة لحماية المحادثات التي نشطت بعد الفحص.'))return;running=true;try{const result=await rpc('clean_chats',{confirm:'DELETE_OLD_CHATS'});let mediaFailure=false;for(let i=0;i<result.media_paths.length;i+=500)try{await req('/functions/v1/family-storage',{method:'POST',body:{action:'remove_old_media',paths:result.media_paths.slice(i,i+500)}});}catch{mediaFailure=true;}box.replaceChildren(element('p','حُذفت '+result.messages+' رسالة من '+result.rooms+' محادثة خاملة.'+(mediaFailure?' تعذّر تنظيف بعض المرفقات القديمة.':'')));await load();}finally{running=false;}},'secondary danger'));});
 return {load,reset(){generation++;running=false;scanned.clear();if(previewUrl)URL.revokeObjectURL(previewUrl);for(const id of ['storage-metrics','storage-records','storage-detail','storage-image-review','storage-chat-review'])$(id).replaceChildren();$('storage-operation').textContent='';}};
}
